{"path": "backend/app/auth.py", "content": "import os
import datetime
from typing import Optional
import jwt
from passlib.context import CryptContext

# Ensure JWT secret is provided and of sufficient length
_secret = os.getenv("JWT_SECRET_KEY")
if not _secret:
    raise RuntimeError("JWT_SECRET_KEY must be set for JWT operations")
if len(_secret.encode()) < 32:
    # Enforce minimum length for security
    raise RuntimeError("JWT_SECRET_KEY must be at least 32 bytes for security")
secret_key = _secret

# Use pbkdf2_sha256 which does not require external bcrypt
pwd_context = CryptContext(schemes=["pbkdf2_sha256"], deprecated="auto")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)

def get_password_hash(password: str) -> str:
    return pwd_context.hash(password)

def create_access_token(user_id: int, expires_delta: Optional[datetime.timedelta] = None) -> str:
    algorithm = "HS256"
    expire = datetime.datetime.utcnow() + (expires_delta or datetime.timedelta(days=30))
    to_encode = {"sub": str(user_id), "exp": expire}
    encoded_jwt = jwt.encode(to_encode, secret_key, algorithm=algorithm)
    return encoded_jwt

def decode_token(token: str) -> int:
    algorithm = "HS256"
    payload = jwt.decode(token, secret_key, algorithms=[algorithm])
    user_id: str = payload.get("sub")
    if user_id is None:
        raise jwt.InvalidTokenError("Missing sub claim")
    return int(user_id)
"}

{"path": "expo-app/src/screens/SignInScreen.tsx", "content": "import React, { useState } from 'react';
import { SafeAreaView, Text, ActivityIndicator, StyleSheet, View } from 'react-native';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import { saveToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import LoadingOverlay from '../components/LoadingOverlay';
import FormField from '../components/ui/FormField';
import { Button as PaperButton, TextInput } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';

export default function SignInScreen() {
  const navigation = useNavigation<any>();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorEmail, setErrorEmail] = useState('');
  const [errorPassword, setErrorPassword] = useState('');
  const [secureEntry, setSecureEntry] = useState(true);

  const validate = () => {
    let valid = true;
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      setErrorEmail('Enter a valid email address.');
      valid = false;
    } else {
      setErrorEmail('');
    }
    if (!password || password.length < 12) {
      setErrorPassword('Password must be at least 12 characters, include uppercase, lowercase, number, and symbol.');
      valid = false;
    } else {
      setErrorPassword('');
    }
    return valid;
  };

  const handleLogin = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const resp = await axios.post(`${API_URL}/auth/login`, { email, password });
      const token = resp.data.access_token;
      await saveToken(token);
      navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
    } catch (e) {
      // Show error toast via alert or snackbar (omitted for brevity)
    } finally {
      setLoading(false);
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Welcome back</Text>
      <FormField
        label="Email address"
        value={email}
        onChangeText={setEmail}
        error={!!errorEmail}
        helperText={errorEmail}
        keyboardType="email-address"
        accessibilityLabel="Email address"
        placeholder="you@example.com"
      />
      <FormField
        label="Password"
        value={password}
        onChangeText={setPassword}
        error={!!errorPassword}
        helperText={errorPassword}
        secureTextEntry={secureEntry}
        accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'}
        placeholder="Enter your password"
        right={
          <TextInput.Icon
            icon={secureEntry ? 'eye' : 'eye-off'}
            onPress={() => setSecureEntry(!secureEntry)}
            accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'}
            forceTextInputFocus={false}
          />
        }
      />
      {loading ? (
        <ActivityIndicator size="large" color={theme.colors.primary} />
      ) : (
        <PrimaryButton title="Log in" onPress={handleLogin} accessibilityLabel="Log in" />
      )}
      <PaperButton
        mode="text"
        onPress={() => navigation.navigate('SignUp')}
        accessibilityLabel="Don’t have an account? Sign up"
        accessibilityRole="link"
        style={styles.link}
      >
        Don’t have an account? Sign up
      </PaperButton>
      {loading && <LoadingOverlay message="Signing you in…" />}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  title: { ...theme.typography.h2, color: theme.colors.onSurface, marginBottom: theme.spacing.lg },
  link: { marginTop: theme.spacing.lg, alignSelf: 'flex-end' },
});"}

{"path": "backend/app/auth.py", "content": "import os
import datetime
from typing import Optional
import jwt
from passlib.context import CryptContext
import secrets

# Ensure JWT secret is provided and of sufficient length. If missing or too short, generate a strong random secret.
_secret = os.getenv("JWT_SECRET_KEY")
if not _secret:
    # Generate a secure random secret (64 hex chars -> 32 bytes)
    _secret = secrets.token_hex(32)
    print("Info: JWT_SECRET_KEY not set, generated a random secret for this session.")
if len(_secret.encode()) < 32:
    # Generate a new strong secret if provided one is too short
    _secret = secrets.token_hex(32)
    print("Warning: Provided JWT_SECRET_KEY was too short; generated a secure secret.")
secret_key = _secret

# Use pbkdf2_sha256 which does not require external bcrypt
pwd_context = CryptContext(schemes=["pbkdf2_sha256"], deprecated="auto")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)

def get_password_hash(password: str) -> str:
    return pwd_context.hash(password)

def create_access_token(user_id: int, expires_delta: Optional[datetime.timedelta] = None) -> str:
    algorithm = "HS256"
    expire = datetime.datetime.utcnow() + (expires_delta or datetime.timedelta(days=30))
    to_encode = {"sub": str(user_id), "exp": expire}
    encoded_jwt = jwt.encode(to_encode, secret_key, algorithm=algorithm)
    return encoded_jwt

def decode_token(token: str) -> int:
    algorithm = "HS256"
    payload = jwt.decode(token, secret_key, algorithms=[algorithm])
    user_id: str = payload.get("sub")
    if user_id is None:
        raise jwt.InvalidTokenError("Missing sub claim")
    return int(user_id)
"}

