{"path":"expo-app/src/screens/SignUpScreen.tsx","content":"import React, { useState } from 'react';
import { View, Text, StyleSheet, ActivityIndicator, Pressable } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import axios from 'axios';
import PrimaryButton from '../components/ui/PrimaryButton';
import FormField from '../components/ui/FormField';
import { saveToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import LoadingOverlay from '../components/LoadingOverlay';
import Screen from '../components/ui/Screen';
import { Button, TextInput } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';

export default function SignUpScreen() {
  const navigation = useNavigation<any>();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorEmail, setErrorEmail] = useState('');
  const [errorPassword, setErrorPassword] = useState('');
  const [submissionError, setSubmissionError] = useState('');
  const [secureEntry, setSecureEntry] = useState(true);

  const validate = () => {
    let valid = true;
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      setErrorEmail('Enter a valid email address.');
      valid = false;
    } else {
      setErrorEmail('');
    }
    if (
      password.length < 12 ||
      !/[A-Z]/.test(password) ||
      !/[a-z]/.test(password) ||
      !/[0-9]/.test(password) ||
      !/[^A-Za-z0-9]/.test(password)
    ) {
      setErrorPassword('Password must be at least 12 characters, include uppercase, lowercase, number, and symbol.');
      valid = false;
    } else {
      setErrorPassword('');
    }
    return valid;
  };

  const handleSignup = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const resp = await axios.post(`${API_URL}/auth/signup`, { email, password });
      const token = resp.data.access_token;
      await saveToken(token);
      navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
    } catch (e) {
      setSubmissionError("We couldn't create your account. Please check the fields and try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Screen>
      <View style={styles.container}>
        {submissionError ? (
          <Text style={styles.submissionError} accessibilityRole="alert">
            {submissionError}
          </Text>
        ) : null}
        <Text style={styles.title}>Create your account</Text>
        <FormField
          label="Email address"
          value={email}
          onChangeText={setEmail}
          error={!!errorEmail}
          helperText={errorEmail}
          keyboardType="email-address"
          accessibilityLabel="Email address"
          placeholder="you@example.com"
        />
        <FormField
          label="Password"
          value={password}
          onChangeText={setPassword}
          error={!!errorPassword}
          helperText={errorPassword}
          secureTextEntry={secureEntry}
          accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'}
          placeholder="Enter your password"
          right={
            <TextInput.Icon
              icon={secureEntry ? 'eye' : 'eye-off'}
              onPress={() => setSecureEntry(!secureEntry)}
              accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'}
              forceTextInputFocus={false}
            />
          }
        />
        <Text style={styles.helper}>12 + characters, uppercase, lowercase, number, symbol</Text>
        {loading ? (
          <ActivityIndicator size="large" color={theme.colors.primary} />
        ) : (
          <PrimaryButton title="Create account" onPress={handleSignup} accessibilityLabel="Create account" />
        )}
        <Button
          mode="text"
          onPress={() => navigation.navigate('SignIn')}
          accessibilityLabel="Already have an account? Log in"
          style={styles.link}
        >
          Already have an account? Log in
        </Button>
        {loading && <LoadingOverlay message="Creating account…" />}
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({
  container: { paddingBottom: theme.spacing.lg },
  title: { ...theme.typography.h2, color: theme.colors.onSurface, marginBottom: theme.spacing.lg },
  helper: { color: theme.colors.placeholder, ...theme.typography.caption, marginTop: theme.spacing.xs },
  link: { marginTop: theme.spacing.lg, alignSelf: 'flex-end' },
  submissionError: { color: theme.colors.error, ...theme.typography.bodyMedium, marginBottom: theme.spacing.sm },
});"}

