{"path": "expo-app/src/screens/MileageEntryScreen.tsx", "content": "import React, { useState, useEffect } from 'react';
import { View, Text, ActivityIndicator, StyleSheet, FlatList } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import FormField from '../components/ui/FormField';
import Screen from '../components/ui/Screen';
import axios from 'axios';
import { Alert } from 'react-native';
import EmptyState from '../components/ui/EmptyState';

export default function MileageEntryScreen() {
  const navigation = useNavigation<any>();
  const [date, setDate] = useState('');
  const [miles, setMiles] = useState('');
  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [entries, setEntries] = useState<any[]>([]);

  const fetchEntries = async () => {
    try {
      const token = await getToken();
      const resp = await axios.get(`${API_URL}/mileage`, { headers: { Authorization: `Bearer ${token}` } });
      setEntries(resp.data);
    } catch (e) {
      // ignore errors for now
    }
  };

  useEffect(() => {
    fetchEntries();
  }, []);

  const handleSave = async () => {
    if (!date || !miles) {
      Alert.alert('Error', 'Please fill all required fields.');
      return;
    }
    setLoading(true);
    try {
      const token = await getToken();
      const payload = { date, miles: parseInt(miles, 10), notes };
      await axios.post(`${API_URL}/mileage`, payload, { headers: { Authorization: `Bearer ${token}` } });
      setMessage('Mileage entry saved.');
      await fetchEntries();
    } catch (e) {
      setMessage('Failed to save mileage. Please try again.');
    } finally {
      setLoading(false);
      setTimeout(() => setMessage(''), 3000);
    }
  };

  const renderItem = ({ item }: { item: any }) => (
    <View style={styles.entry}>
      <Text style={styles.entryText}>{item.miles} miles</Text>
      {item.notes ? <Text style={styles.entryNotes}>{item.notes}</Text> : null}
    </View>
  );

  return (
    <Screen scroll>
      <Text style={styles.title}>New mileage entry</Text>
      <FormField label="Date" value={date} onChangeText={setDate} accessibilityLabel="Date" placeholder="YYYY-MM-DD" />
      <FormField label="Miles driven" value={miles} onChangeText={setMiles} keyboardType="numeric" accessibilityLabel="Miles driven" placeholder="e.g., 120" />
      <FormField label="Notes (optional)" value={notes} onChangeText={setNotes} accessibilityLabel="Notes (optional)" multiline placeholder="Add any extra details…" />
      {loading ? (
        <ActivityIndicator size="large" color={theme.colors.primary} />
      ) : (
        <PrimaryButton title="Save mileage" onPress={handleSave} accessibilityLabel="Save mileage" />
      )}
      {message ? <Text style={styles.message}>{message}</Text> : null}
      {entries.length === 0 ? (
        <EmptyState
          title="No mileage entries yet"
          description="Add mileage to track your travel expenses."
          ctaLabel="Add mileage"
          onPressCTA={() => {}}
        />
      ) : (
        <FlatList
          data={entries}
          keyExtractor={(item) => item.id?.toString() ?? Math.random().toString()}
          renderItem={renderItem}
          style={styles.list}
          ListHeaderComponent={<Text style={styles.listHeader}>Mileage entries</Text>}
        />
      )}
    </Screen>
  );
}

const styles = StyleSheet.create({
  title: { ...theme.typography.headlineMedium, color: theme.colors.onSurface, marginBottom: theme.spacing.lg },
  message: { marginTop: theme.spacing.md, color: theme.colors.success, ...theme.typography.bodyMedium },
  list: { marginTop: theme.spacing.lg },
  listHeader: { ...theme.typography.titleLarge, color: theme.colors.onSurface, marginBottom: theme.spacing.sm },
  entry: { paddingVertical: theme.spacing.sm, borderBottomWidth: 1, borderBottomColor: theme.colors.outline },
  entryText: { ...theme.typography.bodyMedium, color: theme.colors.onSurface },
  entryNotes: { ...theme.typography.bodySmall, color: theme.colors.secondary },
});"}

{"path": "expo-app/src/components/ui/Screen.tsx", "content": "import React from 'react';
import { View, ScrollView, StyleSheet, useWindowDimensions } from 'react-native';
import { theme } from '../../theme';

type Props = {
  children: React.ReactNode;
  scroll?: boolean;
};

export default function Screen({ children, scroll = false }: Props) {
  const Container = scroll ? ScrollView : View;
  const { width } = useWindowDimensions();
  // Determine if we are on a wide screen (desktop) >= 768px
  const isDesktop = width >= 768;
  const containerStyle = [
    styles.container,
    isDesktop ? styles.desktopContainer : styles.mobileContainer,
  ];
  return (
    <Container style={containerStyle} contentContainerStyle={scroll ? styles.scrollContent : undefined}>
      {children}
    </Container>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: theme.colors.background,
    alignSelf: 'center',
  },
  mobileContainer: {
    paddingHorizontal: theme.spacing.lg, // 16px on mobile
    maxWidth: 360,
    paddingTop: theme.spacing.lg,
  },
  desktopContainer: {
    paddingHorizontal: theme.spacing.xl, // 24px on desktop
    maxWidth: 720,
    paddingTop: theme.spacing.xl,
  },
  scrollContent: {
    paddingBottom: theme.spacing.lg,
  },
});
"}

{"path": "expo-app/src/components/ui/TextLink.tsx", "content": "import React from 'react';
import { Pressable, Text, StyleSheet } from 'react-native';
import { theme } from '../../theme';

type Props = {
  onPress: () => void;
  children: React.ReactNode;
  accessibilityLabel?: string;
  testID?: string;
};

export default function TextLink({ onPress, children, accessibilityLabel, testID }: Props) {
  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="link"
      accessibilityLabel={accessibilityLabel}
      testID={testID}
      style={({ pressed }) => [{ opacity: pressed ? 0.6 : 1 }]}
    >
      {({ pressed }) => (
        <Text
          style={[styles.text, pressed && styles.pressed]}
        >
          {children}
        </Text>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  text: {
    color: theme.colors.primary,
    ...theme.typography.button,
    textDecorationLine: 'underline',
  },
  pressed: {
    // underline persists, maybe extra style
  },
});
"}

{"path": "expo-app/src/screens/SignInScreen.tsx", "content": "import React, { useState } from 'react';
import { SafeAreaView, Text, ActivityIndicator, StyleSheet, View } from 'react-native';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import { saveToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import LoadingOverlay from '../components/LoadingOverlay';
import FormField from '../components/ui/FormField';
import { TextInput } from 'react-native-paper';
import Screen from '../components/ui/Screen';
import TextLink from '../components/ui/TextLink';

export default function SignInScreen() {
  const navigation = useNavigation<any>();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorEmail, setErrorEmail] = useState('');
  const [errorPassword, setErrorPassword] = useState('');
  const [secureEntry, setSecureEntry] = useState(true);

  const validate = () => {
    let valid = true;
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      setErrorEmail('Enter a valid email address.');
      valid = false;
    } else {
      setErrorEmail('');
    }
    if (!password || password.length < 12) {
      setErrorPassword('Password must be at least 12 characters, include uppercase, lowercase, number, and symbol.');
      valid = false;
    } else {
      setErrorPassword('');
    }
    return valid;
  };

  const handleLogin = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const resp = await axios.post(`${API_URL}/auth/login`, { email, password });
      const token = resp.data.access_token;
      await saveToken(token);
      navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
    } catch (e) {
      // Show error toast via alert or snackbar (omitted for brevity)
    } finally {
      setLoading(false);
    }
  };

  return (
    <Screen>
      <SafeAreaView style={styles.container}>
        <Text style={styles.title}>Welcome back</Text>
        <FormField
          label="Email address"
          value={email}
          onChangeText={setEmail}
          error={!!errorEmail}
          helperText={errorEmail}
          keyboardType="email-address"
          accessibilityLabel="Email address"
          placeholder="you@example.com"
        />
        <FormField
          label="Password"
          value={password}
          onChangeText={setPassword}
          error={!!errorPassword}
          helperText={errorPassword}
          secureTextEntry={secureEntry}
          accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'}
          placeholder="Enter your password"
          right={
            <TextInput.Icon
              icon={secureEntry ? 'eye' : 'eye-off'}
              onPress={() => setSecureEntry(!secureEntry)}
              accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'}
              forceTextInputFocus={false}
            />
          }
        />
        {loading ? (
          <ActivityIndicator size="large" color={theme.colors.primary} />
        ) : (
          <PrimaryButton title="Log in" onPress={handleLogin} accessibilityLabel="Log in" />
        )}
        <TextLink
          onPress={() => navigation.navigate('SignUp')}
          accessibilityLabel="Don’t have an account? Sign up"
        >
          Don’t have an account? Sign up
        </TextLink>
        {loading && <LoadingOverlay message="Signing you in…" />}
      </SafeAreaView>
    </Screen>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  title: { ...theme.typography.h2, color: theme.colors.onSurface, marginBottom: theme.spacing.lg },
});"}

